const job=$('Next todo job').first().json;
const raw=Buffer.from(($('Read world PLAN.md').first().json.content||''),'base64').toString('utf8');
const cut=raw.indexOf('\n## 4')>0?raw.slice(0,raw.indexOf('\n## 4')):raw; const plan=cut.slice(0,7000);
const rules=$('Read GTM rules').all().map(r=>r.json.summary).filter(Boolean).join('\n');
const prior=$('Read team drafts').all().map(r=>r.json).filter(r=>r.item&&r.output).sort((a,b)=>a.item_no-b.item_no)
 .map(r=>'['+r.item_no+' '+r.item+'] '+String(r.output).replace(/\s+/g,' ').slice(0,500)).join('\n').slice(0,3500);
const B={1:"Site map (pages + purpose) and full copy for home, product, pricing, about, contact, privacy notice outline. Mobile-first, Telugu+English where the plan says so. Hero headline options x3.",
2:"The most profitable sub-niche to start with: score 3-5 candidate segments on pain, ability to pay, reachability from Hyderabad with 1 hour/day, competition, delivery cost. Pick one with reasons.",
3:"Top 5-8 real competitors (Indian first, then global) with price, positioning, strengths, gaps, and how we win. Name only companies you are confident exist; mark uncertain facts [TO VERIFY].",
4:"Ideal customer profile: firmographics, the person who decides, jobs-to-be-done, top pains in their words, triggers to buy, disqualifiers, where they hang out, budget.",
5:"Exactly where to find potential customers legally: named directories, associations, events, online communities, OpenStreetMap categories, partners, inbound sources. A weekly sourcing routine with target counts.",
6:"Lead generation plan: inbound and outbound mix, lead magnet, lead scoring rules (0-100) with fields for the KL Leads table, weekly volume targets, owner per step.",
7:"The offer: core promise, deliverables, guarantee that we can honour, bonuses, founding-customer terms, what is NOT included. Use the approved prices from the plan only.",
8:"Pricing: tiers and exact INR prices consistent with the plan, unit economics (cost to serve, margin), discount rules, payment terms, GST note. Show the maths.",
9:"Cold email sequence: 5 emails (day 0, 3, 7, 12, 20), subject lines (36-50 chars), bodies under 120 words, plain text, one ask each, merge fields, opt-out line and sender identity.",
10:"Personalised outreach: research checklist per prospect, 5 personalisation hooks, templates for email, LinkedIn (manual), WhatsApp reply (only after opt-in) and in-person visit opener, with 2 filled examples using fictional businesses.",
11:"Sales proposal template: problem, solution, scope, timeline, price table, terms, next step, signature block. Fill one example for a typical customer.",
12:"One campaign landing page: headline, subhead, 3 benefit blocks, how it works, proof section (no fake testimonials), pricing teaser, FAQ (6), CTA and form fields, plus A/B headline variants.",
13:"30-day marketing content plan: pillars, platforms, cadence, 12 post ideas with hooks, 2 long-form pieces, repurposing map. Respect ASCI/SEBI rules.",
14:"Ad creatives: 6 ad concepts (Meta + Google) with primary text, headline, description, visual brief for 1080x1080 and 1080x1920, targeting, budget test plan in INR, success metric.",
15:"Sales funnel: stages from stranger to paying customer to referral, conversion target per stage, assets and agent owner per stage, leak checks.",
16:"CRM automation design on n8n: pipeline stages for the KL Pipeline table, fields, triggers, automatic tasks, alerts to Akhil on Telegram, data retention and DPDP notes.",
17:"Follow-up sequences: after inquiry, after demo, after proposal, after no-reply, after purchase; channel, timing and message for each step.",
18:"Sales call script: opener, permission, 8 discovery questions, demo flow, pricing moment, close, next-step booking. Telugu/English mix where natural.",
19:"Objection handling: the 12 most likely objections with a short, honest answer and a question back. No pressure tactics.",
20:"Case studies: we have no customers yet. Write the case-study template, the data to capture from the first pilot (baseline, after, quote with permission), and the consent wording. No invented results.",
21:"Customer onboarding system: day 0-30 checklist, welcome message, setup steps, training, first-value milestone, health check, handover to support.",
22:"Repetitive tasks to automate: list 10 with current time cost, n8n workflow design for each, which agent runs it, risk if it fails.",
23:"KPIs: north-star metric, 8-10 weekly KPIs with formulas and targets, where each number comes from (table/source), and the weekly review ritual.",
24:"Conversion improvement: 8 experiments ranked by impact/effort (ICE), hypothesis, metric, sample size needed, how to run each with zero budget."};
const sys='You are '+job.owner_agent+', a senior '+job.pod+' specialist in the Kalpa Labs '+job.stream+' revenue team (Hyderabad, India). Akhil is the CEO: beginner, 1 hour a day, free tools only, no money taken until delivery is proven live. Write world-class, specific, ready-to-use work in plain English, not generic advice. Never invent customers, testimonials, statistics or company facts; mark anything unverified [TO VERIFY]. Mark anything only Akhil can do with [CEO]. Follow every rule below. Stay consistent with the plan and with the team drafts.';
const user='RULES:\n'+rules+'\n\nBUSINESS PLAN (excerpt):\n'+plan+'\n\nTEAM DRAFTS SO FAR:\n'+(prior||'none yet')+'\n\nYOUR TASK - item '+job.item_no+' of 24: '+job.item+'\n'+B[job.item_no]+'\n\nOutput: Markdown, 500-1000 words, headings and tables where useful. End with "Next 3 actions" (owner + minutes).';
return [{json:{id:job.id,stream:job.stream,item_no:job.item_no,system:sys,prompt:user}}];

